//
// The request state of a paginated route, kept per consumer key: the query it last
// sent (the route's arguments, the position, the requested size, the sort and the
// filters) and the page envelope that answered it. One request loads one page.
//
// Changing the size, the sort or a filter returns to the first page, and so does
// loading other arguments. A page answering with a different size than the one the
// query expected -- the size it requested, or else the size the page before it
// answered -- was cut under a size that has since changed, so its position is no
// longer a page boundary: the query restarts from the first page.
//
// The page shown stays shown while the next one is awaited; a failed request for the
// query that page answers keeps it beside the failure, and any other failed request
// drops it -- the rule every keyed request follows (`requests.ts`).

import type { ProblemDetails } from '@marram/system-api-common';

import { type PageEnvelope, type PositionAdvance, pagerView, positionOf, requirePageSize } from './pager';
import { type KeyedRequests, type RequestStatus, sameArgs } from './requests';

/** A sort direction. */
export type SortOrder = 'asc' | 'desc';

/** The one column a paginated route is sorted by, and its direction. */
export interface SortState<S extends string> {
  readonly by: S;
  readonly order: SortOrder;
}

/** The `aria-sort` value of a sortable column header. */
export type AriaSort = 'none' | 'ascending' | 'descending';

/**
 * The sort after pressing *column*'s header under *current*: a column cycles none,
 * ascending, descending, none; another column's header starts ascending.
 */
export function nextSort<S extends string>(current: SortState<S> | null, column: S): SortState<S> | null {
  if (current === null || current.by !== column) {
    return { by: column, order: 'asc' };
  }
  return current.order === 'asc' ? { by: column, order: 'desc' } : null;
}

/** The `aria-sort` of *column*'s header under *current*. */
export function ariaSort<S extends string>(current: SortState<S> | null, column: S): AriaSort {
  if (current === null || current.by !== column) {
    return 'none';
  }
  return current.order === 'asc' ? 'ascending' : 'descending';
}

/** Everything one page request of a paginated route sends. */
export interface PagedQuery<A, F, S extends string> {
  readonly args: A;
  /** A row offset or a page index, as the backend counts positions. */
  readonly position: number;
  /** The number of rows per page requested, or `null` for the server's own choice. */
  readonly size: number | null;
  readonly sort: SortState<S> | null;
  readonly filters: F;
  /** The size the page before this one answered, when this query moved past it without requesting a size. */
  readonly expectedLimit: number | null;
}

/** One key's request of a paginated route. `rows` are entity ids for a route over an entity, else the rows. */
export interface PagedRequest<A, F, S extends string, R> {
  readonly query: PagedQuery<A, F, S>;
  readonly requestId: number;
  readonly status: RequestStatus;
  /** The page shown, kept while a newer request is awaited. */
  readonly rows: readonly R[];
  readonly envelope: PageEnvelope | null;
  /** The query the page shown answers, or `null` while no page is shown. */
  readonly answered: PagedQuery<A, F, S> | null;
  readonly error: ProblemDetails | null;
}

/**
 * The first page of *args*, keeping the size, the sort and the filters of the *previous*
 * query; without one, requesting *initialSize* rows (`null` for the server's own choice).
 */
export function firstPageQuery<A, F, S extends string>(
  args: A,
  previous: PagedQuery<A, F, S> | null,
  emptyFilters: F,
  initialSize: number | null,
): PagedQuery<A, F, S> {
  return {
    args,
    position: 0,
    size: previous === null ? (initialSize === null ? null : requirePageSize(initialSize)) : previous.size,
    sort: previous === null ? null : previous.sort,
    filters: previous === null ? emptyFilters : previous.filters,
    expectedLimit: null,
  };
}

/** *query* at its first page. */
export function restartQuery<A, F, S extends string>(query: PagedQuery<A, F, S>): PagedQuery<A, F, S> {
  return { ...query, position: 0, expectedLimit: null };
}

/**
 * *query* at page *index* (zero-based) of the pages *envelope* answered, or `null`
 * when *index* names no such page.
 */
export function withPageIndex<A, F, S extends string>(
  query: PagedQuery<A, F, S>,
  envelope: PageEnvelope,
  index: number,
  advance: PositionAdvance,
): PagedQuery<A, F, S> | null {
  const { pageCount } = pagerView(envelope, 0);
  if (!Number.isInteger(index) || index < 0 || index >= pageCount) {
    return null;
  }
  return { ...query, position: positionOf(index, envelope.limit, advance), expectedLimit: envelope.limit };
}

/**
 * *query* requesting pages of *size* rows, from the first page. The server bounds the
 * size and refuses one outside its bounds; a size that is not a positive whole number
 * is refused here.
 */
export function withPageSize<A, F, S extends string>(query: PagedQuery<A, F, S>, size: number): PagedQuery<A, F, S> {
  return { ...restartQuery(query), size: requirePageSize(size) };
}

/** *query* sorted by *sort* (or unsorted), from the first page. */
export function withSort<A, F, S extends string>(
  query: PagedQuery<A, F, S>,
  sort: SortState<S> | null,
): PagedQuery<A, F, S> {
  return { ...restartQuery(query), sort };
}

/** *query* filtered by *filters*, from the first page. */
export function withFilters<A, F, S extends string>(query: PagedQuery<A, F, S>, filters: F): PagedQuery<A, F, S> {
  return { ...restartQuery(query), filters };
}

/** Whether *envelope*, answering *query*, was cut under another size than the query expected. */
export function pageNeedsRestart<A, F, S extends string>(query: PagedQuery<A, F, S>, envelope: PageEnvelope): boolean {
  const expected = query.size ?? query.expectedLimit;
  return query.position !== 0 && expected !== null && envelope.limit !== expected;
}

/**
 * *requests* with *key* loading *query* under *requestId*. The page shown stays shown
 * while the new answer is awaited, whatever query it answers.
 */
export function startPage<A, F, S extends string, R>(
  requests: KeyedRequests<PagedRequest<A, F, S, R>>,
  key: string,
  requestId: number,
  query: PagedQuery<A, F, S>,
): KeyedRequests<PagedRequest<A, F, S, R>> {
  const previous = requests[key];
  return {
    ...requests,
    [key]: {
      query,
      requestId,
      status: 'loading',
      rows: previous === undefined ? [] : previous.rows,
      envelope: previous === undefined ? null : previous.envelope,
      answered: previous === undefined ? null : previous.answered,
      error: null,
    },
  };
}

/**
 * *requests* with *key*'s request *requestId* failed with *problem*; unchanged when
 * that request is stale. The page shown stays beside the failure when it answers the
 * same query (a refresh failed), and is dropped when it answers another (a load failed).
 */
export function failPage<A, F, S extends string, R>(
  requests: KeyedRequests<PagedRequest<A, F, S, R>>,
  key: string,
  requestId: number,
  problem: ProblemDetails,
): KeyedRequests<PagedRequest<A, F, S, R>> {
  const current = requests[key];
  if (current === undefined || current.requestId !== requestId) {
    return requests;
  }
  const refreshed = current.answered !== null && sameArgs(current.answered, current.query);
  return {
    ...requests,
    [key]: {
      ...current,
      status: 'failed',
      rows: refreshed ? current.rows : [],
      envelope: refreshed ? current.envelope : null,
      answered: refreshed ? current.answered : null,
      error: problem,
    },
  };
}

/**
 * *requests* with *key*'s request *requestId* answered by *rows* under *envelope* --
 * `null` for a route declaring an optional page that answered none; unchanged when
 * that request is stale.
 */
export function settlePage<A, F, S extends string, R>(
  requests: KeyedRequests<PagedRequest<A, F, S, R>>,
  key: string,
  requestId: number,
  rows: readonly R[],
  envelope: PageEnvelope | null,
): KeyedRequests<PagedRequest<A, F, S, R>> {
  const current = requests[key];
  if (current === undefined || current.requestId !== requestId) {
    return requests;
  }
  return { ...requests, [key]: { ...current, status: 'loaded', rows, envelope, answered: current.query, error: null } };
}
